function updateDeepDive(t){selectedTrialArea=t;selectedGapOpportunity=null;if(!t)return;const path=t.path||[t.area],members=t.members||[],label=path.join(" → ");const years=members.map(x=>(trialPaperMap.get(x.openalex_id)||x).publication_year).filter(Boolean),yr=years.length?`${Math.min(...years)}–${Math.max(...years)}`:"TIDAK_TERCATAT",subs=computeSubareas(members,path).slice(0,6),opps=gapOpportunities(members,path);deepDiveTitle.textContent=`Pendalaman: ${label}`;deepDiveState.textContent="PRELIMINARY";deepDiveState.className="state blue";deepDiveSummary.innerHTML=`<strong>Evidence Summary · ${esc(members.length)} paper</strong><br>Subset ini dipilih HUMAN melalui <strong>${esc(label)}</strong> dan mencakup publikasi ${esc(yr)}. Konteks judul yang berulang berikutnya: ${subs.length?subs.map(([x,n])=>`${esc(x)} (${n})`).join(", "):"belum ada sinyal berulang yang cukup"}.<br><strong>Batas bukti:</strong> ringkasan ini berbasis metadata/judul. Abstrak, metode, unit analisis, temuan, dan full text belum diverifikasi.<br><small>Ini evidence summary awal, bukan kesimpulan literatur.</small>`;if(deepDiveOpportunities)deepDiveOpportunities.innerHTML=`<h4>Arah pemeriksaan · pilih konteks untuk screening</h4>${opps.length?opps.map(o=>`<article class="gap-card"><div><span class="state gray">${esc(o.id)}</span> <strong>${esc(o.term)}</strong></div><p><strong>Observasi:</strong> ${esc(o.observation)}</p><p><strong>WHY:</strong> ${esc(o.why)}</p><p><strong>Yang belum diketahui:</strong> ${esc(o.limitation)}</p><p><strong>Verifikasi berikutnya:</strong> ${esc(o.verification)}</p><button class="secondary-action gap-select" type="button" data-term="${esc(o.term)}">Pilih opportunity ini</button></article>`).join(""):"<div class=\"callout\">Belum ada gap opportunity berbasis sinyal judul yang cukup. Periksa paper atau pilih konteks lain.</div>"}<small>Ini belum research gap. Pilihan konteks membuka Screening Advice; HUMAN kemudian memilih evidence set.</small>`;deepDiveOpportunities?.querySelectorAll(".gap-select").forEach(b=>b.onclick=()=>{const term=b.dataset.term,o=opps.find(x=>x.term===term);selectedGapOpportunity=o?{...o,path:[...path],parent_member_count:members.length,scientific_decision:false,canonical_write:false}:null;deepDiveOpportunities.querySelectorAll(".gap-card").forEach(x=>x.classList.remove("selected"));b.closest(".gap-card")?.classList.add("selected");showOpportunityAnalysis(o,path,members);trialDecisionState.innerHTML=`<strong>Gap Opportunity dipilih HUMAN: ${esc(label)} → ${esc(term)}</strong><br>${esc(o?.observation||"")}<br><strong>Verifikasi:</strong> ${esc(o?.verification||"")}<br><small>Pilihan ini akan ikut dibawa ke Research Copilot · scientific decision: false · canonical write: false</small>`;});deepDiveInspect.disabled=false;deepDiveCopilot.disabled=false;if(deepDiveAdvanced){const isUrban=path.join("|")==="smart|city|urban";deepDiveAdvanced.hidden=!isUrban;if(isUrban){deepDiveAdvanced.innerHTML=`<strong>ADVANCED EVIDENCE · smart → city → urban</strong><br>19/19 abstract OpenAlex tersedia pada verification pass. <button id="urban-advanced" class="secondary-action" type="button">Periksa evidence & Saran Riset advanced</button>`;document.getElementById("urban-advanced").onclick=renderUrbanAdvanced;}}}
