const trialDrill=document.getElementById("trial-drilldown"),trialSubareas=document.getElementById("trial-subareas"),trialBreadcrumb=document.getElementById("trial-breadcrumb"),trialDrillCount=document.getElementById("trial-drill-count"),trialStopDrill=document.getElementById("trial-stop-drill"),trialResetDrill=document.getElementById("trial-reset-drill");
