const drillStop=new Set(["the","and","for","with","from","this","that","using","use","into","based","study","analysis","research","artificial","intelligence","digital","government","public","services","service","of","in","on","to","a","an"]);
function titleTerms(title){return [...new Set((String(title||"").toLowerCase().match(/[a-z][a-z-]{2,}/g)||[]).filter(x=>!drillStop.has(x)))];}
function computeSubareas(members,path){const counts=new Map(),chosen=new Set(path);for(const m of members){const p=trialPaperMap.get(m.openalex_id)||m;for(const term of titleTerms(p.title))if(!chosen.has(term))counts.set(term,(counts.get(term)||0)+1);}return [...counts].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).filter(([,n])=>n>=3).slice(0,20);}

async function renderUrbanAdvanced(){if(!trialAdvice)return;trialAdvice.innerHTML='<h3>Saran Riset Advanced · smart → city → urban</h3><p>Memuat 19 abstract terverifikasi…</p>';try{const r=await fetch(`${API_BASE}/api/trial/research-value/smart-city-urban-abstracts`,{cache:"no-store"});if(!r.ok)throw new Error(`HTTP ${r.status}`);const x=await r.json(),ps=x.papers||[],available=ps.filter(p=>p.abstract);const specs=[{id:"A",name:"governance → lived outcomes",re:/governance|policy|livability|quality of life|wellbeing|community|inclusion|literacy/i,q:"Apakah governance digital benar-benar dihubungkan dengan lived outcomes warga, bukan hanya implementasi teknologi?"},{id:"B",name:"AI governance → urban infrastructure",re:/artificial intelligence|\bAI\b|algorithm|infrastructure|vulnerabil|ethic|accountab/i,q:"Bagaimana AI/algorithmic governance mengubah risiko, accountability, dan tata kelola infrastruktur kota?"},{id:"C",name:"context transferability",re:/china|sydney|australia|europe|india|singapore|indonesia/i,q:"Apakah mekanisme dan temuan smart-city dapat ditransfer lintas konteks kota/negara?"},{id:"D",name:"implementation mechanism",re:/implementation|mechanism|strategy|planning|resilien|sustainab|innovation/i,q:"Mekanisme apa yang menjembatani smart-city strategy dengan outcome urban?"}];const counts=specs.map(o=>{const papers=available.filter(p=>o.re.test(p.abstract||"")),paperIds=new Set(papers.map(p=>p.openalex_id));return {...o,papers,counterCandidates:available.filter(p=>!paperIds.has(p.openalex_id))};});trialAdvice.innerHTML=`<h3>Saran Riset Advanced · smart → city → urban</h3><div class="callout"><strong>Evidence Summary berbasis abstract</strong><br>${available.length}/${ps.length} abstract tersedia. Opportunity berikut dibentuk sebagai jalur verifikasi, bukan ranking atau research gap final.<br><small>Abstract evidence masih harus diuji terhadap metode, hasil, limitation, counter-evidence, dan full text.</small></div><div class="advice-grid">${counts.map(o=>`<div class="advice-card advanced-opportunity"><strong>Opportunity ${o.id} · ${esc(o.name)}</strong><p>${esc(o.q)}</p><p><strong>Supporting signal:</strong> ${o.papers.length}/${available.length} abstract cocok dengan sinyal teks awal.</p><button class="secondary-action advanced-select" data-opp="${o.id}" type="button">Periksa opportunity ${o.id}</button></div>`).join("")}</div><div id="advanced-evidence-detail" class="callout"><strong>Pilih satu opportunity</strong><br>GFPROJCLAW akan menampilkan supporting papers yang dapat ditelusuri dan pertanyaan counter-evidence untuk HUMAN.</div><div class="callout warning"><strong>HUMAN verification required.</strong> Sistem belum menetapkan gap, novelty, relevance, atau keputusan evidence.</div>`;const detail=document.getElementById("advanced-evidence-detail");trialAdvice.querySelectorAll(".advanced-select").forEach(b=>b.onclick=()=>{const o=counts.find(z=>z.id===b.dataset.opp);selectedGapOpportunity={id:`ADV-${o.id}`,term:o.name,observation:`${o.papers.length}/${available.length} abstract memberi supporting text signal.`,why:o.q,limitation:"Abstract-level verification only; methods/results/full text and counter-evidence remain to be checked.",verification:"Inspect supporting papers and deliberately test counter-evidence before HUMAN judgment.",path:["smart","city","urban"],parent_member_count:available.length,supporting_papers:o.papers.map(p=>({openalex_id:p.openalex_id,title:p.title,doi:p.doi,source_url:p.source_url,abstract:p.abstract,abstract_state:p.abstract_state})),counter_evidence_candidates:o.counterCandidates.map(p=>({openalex_id:p.openalex_id,title:p.title,doi:p.doi,source_url:p.source_url,abstract:p.abstract,abstract_state:p.abstract_state})),counter_evidence_instruction:"Inspect these remaining papers for substantive contrary mechanisms/results; keyword absence alone is not counter-evidence.",evidence_level:"ABSTRACT_ONLY",scientific_decision:false,canonical_write:false};const support=o.papers;detail.innerHTML=`<strong>Opportunity ${o.id} · ${esc(o.name)}</strong><p><strong>Pertanyaan verifikasi:</strong> ${esc(o.q)}</p><p><strong>Supporting papers untuk diperiksa (${o.papers.length} terdeteksi):</strong></p>${support.map(p=>`<div class="advanced-paper"><strong>${esc(p.title||"JUDUL TIDAK TERSEDIA")}</strong><br><small>${p.source_url?`<a href="${esc(p.source_url)}" target="_blank" rel="noopener">OpenAlex ↗</a>`:""}${p.doi?` · <a href="${esc(p.doi)}" target="_blank" rel="noopener">DOI ↗</a>`:""}</small><details><summary>Baca abstract</summary><p>${esc(p.abstract||"Abstract tidak tersedia")}</p></details></div>`).join("")}<p><strong>Counter-evidence candidates (${o.counterCandidates.length}):</strong> paper lain pada subset 19 yang tidak masuk supporting text signal. HUMAN tetap harus membaca abstract; ketidakcocokan keyword bukan counter-evidence.</p>${o.counterCandidates.map(p=>`<div class="advanced-paper counter-candidate"><strong>${esc(p.title||"JUDUL TIDAK TERSEDIA")}</strong><br><small>${p.source_url?`<a href="${esc(p.source_url)}" target="_blank" rel="noopener">OpenAlex ↗</a>`:""}${p.doi?` · <a href="${esc(p.doi)}" target="_blank" rel="noopener">DOI ↗</a>`:""}</small><details><summary>Baca abstract untuk challenge</summary><p>${esc(p.abstract||"Abstract tidak tersedia")}</p></details></div>`).join("")}<button id="advanced-to-copilot" class="primary-action" type="button">Bawa opportunity + evidence ke Research Copilot →</button>`;document.getElementById("advanced-to-copilot").onclick=()=>{if(!selectedTrialArea)return;sessionStorage.setItem("gfprojclaw-explorer-handoff",JSON.stringify(buildCopilotHandoff(selectedTrialArea)));window.location.href="index.html?from=explorer&view=handoff";};detail.scrollIntoView({behavior:"smooth",block:"center"});});trialAdvice.scrollIntoView({behavior:"smooth",block:"start"});}catch(e){trialAdvice.innerHTML=`<h3>Saran Riset Advanced</h3><p>Evidence abstract tidak tersedia: ${esc(e.message)}</p>`;}}
function renderAdviceForContext(){if(!drillPath.length)return;const label=drillPath.join(" → "),members=drillMembers,venues=[...new Set(members.map(x=>(trialPaperMap.get(x.openalex_id)||x).venue).filter(Boolean))].slice(0,5),years=members.map(x=>(trialPaperMap.get(x.openalex_id)||x).publication_year).filter(Boolean),yr=years.length?`${Math.min(...years)}–${Math.max(...years)}`:"TIDAK_TERCATAT";if(trialAdvice)trialAdvice.innerHTML=`<h3>Saran Riset · ${esc(label)}</h3><div class="advice-grid"><div class="advice-card"><strong>Apa yang kami amati</strong>${esc(members.length)} paper berada pada intersection jalur HUMAN “${esc(label)}” berdasarkan istilah judul, periode ${esc(yr)}. Contoh venue: ${esc(venues.join(", ")||"TIDAK_TERCATAT")}.</div><div class="advice-card"><strong>Mengapa ini mungkin penting</strong>Jalur ini dipilih HUMAN dari struktur yang teramati. Frekuensi/intersection tidak membuktikan relevansi, gap, atau novelty.</div><div class="advice-card"><strong>Apa yang perlu diperiksa berikutnya</strong>Periksa variasi penggunaan istilah, tahun, venue, abstrak, metode, dan konteks pada paper anggota sebelum penggunaan ilmiah.</div><div class="advice-card"><strong>Pertanyaan untuk Anda</strong>Apakah kedalaman “${esc(label)}” sudah cukup untuk dibawa ke reasoning lebih lanjut, atau Anda perlu kembali dan memilih cabang lain?</div></div><small>Saran berasal dari subset corpus yang dapat ditelusuri; HUMAN tetap menentukan makna dan arah riset.</small>`;renderTrialPapers(members);const root=(trialWhy?.traces||[]).find(x=>x.area===drillPath[0]);if(root)updateDeepDive({...root,area:label,path:[...drillPath],members});trialAdvice.scrollIntoView({behavior:"smooth",block:"start"});}
function renderDrill(){trialDrill.hidden=false;trialBreadcrumb.innerHTML=`<strong>Semesta Riset</strong> → ${drillPath.map((x,i)=>`<button type="button" data-depth="${i}">${esc(x)}</button>`).join(" → ")}`;trialDrillCount.textContent=`${drillMembers.length} PAPER`;const subs=computeSubareas(drillMembers,drillPath);trialSubareas.innerHTML=subs.map(([term,n])=>`<button class="trial-area" type="button" data-term="${esc(term)}"><strong>${esc(term)}</strong><br><small>${esc(n)} paper pada subset ini</small></button>`).join("")||'<div class="callout">Tidak ada konteks lanjutan yang cukup sering teramati. Anda dapat meminta Saran Riset pada kedalaman ini.</div>';trialSubareas.querySelectorAll("button").forEach(b=>b.onclick=()=>drillInto(b.dataset.term));trialBreadcrumb.querySelectorAll("button").forEach(b=>b.onclick=()=>{const keep=drillPath.slice(0,Number(b.dataset.depth)+1);startDrillPath(keep);});}
function startDrillPath(path){const root=(trialWhy?.traces||[]).find(x=>x.area===path[0]);if(!root)return;let members=root.members||[];for(const term of path.slice(1))members=members.filter(m=>titleTerms((trialPaperMap.get(m.openalex_id)||m).title).includes(term));drillPath=path;drillMembers=members;renderDrill();renderTrialPapers(members);updateDeepDive({...root,area:path.join(" → "),path:[...path],members});}
function drillInto(term){startDrillPath([...drillPath,term]);trialAreaDetail.innerHTML=`<strong>JALUR HUMAN</strong> · ${drillPath.map(esc).join(" → ")}<br><strong>${esc(drillMembers.length)} paper</strong> pada intersection istilah judul ini.<br><small>Anda dapat masuk lebih dalam atau berhenti dan meminta Saran Riset.</small>`;}
function showTrialArea(term){const t=(trialWhy?.traces||[]).find(x=>x.area===term);if(!t)return;trialAreaDetail.innerHTML=`<strong>MENGAPA ${esc(term)}</strong><br>${esc(t.why_shown)}<br><strong>Observasi pendukung:</strong> ${esc(t.supporting_observation?.observed_title_count)} anggota tepat berdasarkan istilah pada judul.<br><small>Pilih sub-area untuk bergerak global → detail, atau berhenti pada kedalaman yang cukup bagi Anda.</small>`;startDrillPath([term]);if(trialAdvice)trialAdvice.innerHTML=`<h3>Saran Riset</h3><p>Belum ditampilkan. Eksplorasi sub-area terlebih dahulu, atau pilih <strong>“Cukup — berikan Saran Riset untuk konteks ini”</strong>.</p>`;renderTrialPapers(t.members||[]);}
if(trialStopDrill)trialStopDrill.onclick=renderAdviceForContext;
if(trialResetDrill)trialResetDrill.onclick=()=>{drillPath=[];drillMembers=[];trialDrill.hidden=true;trialAreaDetail.textContent="Pilih area global lain untuk memulai pendalaman.";};
async function loadResearchValueTrial(){
 if(!trialState)return;
 try{
  const [lr,wr,pr,cr]=await Promise.all(["landscape","why","papers","coverage"].map(x=>fetch(`${API_BASE}/api/trial/research-value/${x}`,{cache:"no-store"})));if([lr,wr,pr,cr].some(r=>!r.ok))throw new Error("payload uji tidak tersedia");
  const [l,w,p,c]=await Promise.all([lr.json(),wr.json(),pr.json(),cr.json()]);trialWhy=w;trialPaperMap=new Map((p.papers||[]).map(x=>[x.openalex_id,x]));
  trialState.textContent="SELURUH SEMESTA TERBATAS";trialState.className="state green";
  const cv=l.coverage||{};trialCoverage.innerHTML=`<strong>${esc(cv.raw_retrieved_count)} / ${esc(cv.provider_reported_total)} record mentah OpenAlex berhasil diambil</strong> · ${esc(cv.retrieved_count)} anggota setelah deduplikasi<br><small>Observasi provider yang dibatasi query/waktu · bukan jumlah relevan secara ilmiah · penulisan canonical: false</small>`;
  trialYears.innerHTML=Object.entries(l.year_landscape||{}).sort().map(([y,n])=>`<article class="trial-metric"><span>${esc(y)}</span><strong>${esc(n)}</strong></article>`).join("");
  trialAreas.innerHTML=(l.observed_areas||[]).map(a=>`<button class="trial-area" type="button" data-term="${esc(a.term)}"><strong>${esc(a.term)}</strong><br><small>${esc(a.observed_count)} observasi judul</small></button>`).join("");trialAreas.querySelectorAll("button").forEach(b=>b.onclick=()=>showTrialArea(b.dataset.term));
  const cov=c.coverage||{};trialBlindspots.innerHTML=`<strong>Diamati:</strong> ${esc((cov.searched_sources||[]).join(", "))}<br><strong>Belum dicari secara seluruh-semesta-terbatas:</strong> ${esc((cov.not_searched_sources||[]).join(", "))}<br>${esc(c.blind_spot_statement)}<br><small>Abstrak diambil: ${esc(cov.abstracts_retrieved)} · Teks lengkap diperiksa: ${esc(cov.full_text_checked)}</small>`;
  trialDecisions.innerHTML=(c.human_decision_options||[]).map(x=>`<button class="secondary-action" type="button" data-decision="${esc(x)}">${esc(x.replaceAll("_"," "))}</button>`).join("");trialDecisions.querySelectorAll("button").forEach(b=>b.onclick=()=>{trialDecisionState.innerHTML=`<strong>Refleksi scope HUMAN lokal: ${esc(b.dataset.decision)}</strong><br><small>Hanya pratinjau · tidak ada penulisan canonical · bukan keputusan ilmiah mesin.</small>`});
  if(l.observed_areas?.length)showTrialArea(l.observed_areas[0].term);
 }catch(e){trialState.textContent="TIDAK_TERSEDIA";trialCoverage.textContent=`Lanskap uji tidak tersedia: ${e.message}`;}
}
loadResearchValueTrial();

const acceptPreview=document.getElementById("accept-preview"),acceptResult=document.getElementById("accept-result");
if(acceptPreview)acceptPreview.onclick=()=>{
 const ids=["accept-landscape","accept-why","accept-trace","accept-limits"],passed=ids.filter(id=>document.getElementById(id)?.checked).length,rationale=document.getElementById("accept-rationale")?.value.trim()||"";
 if(passed<4||!rationale){acceptResult.innerHTML=`<strong>MENUNGGU</strong> · ${passed}/4 pemeriksaan penerimaan dikonfirmasi. Alasan HUMAN ${rationale?"tercatat":"wajib diisi"}.<br><small>GFPROJCLAW tidak dapat menyatakan sendiri bahwa dirinya bermanfaat secara ilmiah.</small>`;return;}
 acceptResult.innerHTML=`<strong>SIAP UNTUK CATATAN PENERIMAAN HUMAN</strong> · 4/4 pemeriksaan dikonfirmasi beserta alasan.<br><small>Pratinjau lokal ini bukan penerimaan canonical. HUMAN harus mencatat keputusan akhir secara eksplisit.</small>`;
};
